params.name:
// Keep usePlatformDefaultWidth = true (the default) to avoid measurement
    // crashes on devices that don't support custom-width dialogs in all
    // configurations. Callers can override if they need it.
    properties

// ── Visible items ────────────────────────────────────────────────────
    /** Number of slides visible simultaneously. Arrows still scroll one at a time. */
    visibleItems

// ── Clear button (single mode only) ──────────────────────────────────
    /** Show an × button inside the trigger when a value is selected. */
    showClear

// ── Groups ────────────────────────────────────────────────────────────
    /** Optional group definitions. Items are bucketed by [KComboboxItem.group]. */
    groups

// ── Custom item ───────────────────────────────────────────────────────
    /** Override the default label row with a fully custom composable per item. */
    customItem

// ── Input group addon ─────────────────────────────────────────────────
    /** Leading slot rendered left of the trigger label (icon, flag, etc.). */
    addon

// ── Auto-highlight ────────────────────────────────────────────────────
    /** Automatically highlight the first filtered item when query changes. */
    autoHighlight

params.default:
KeyboardOptions.Default.copy(
        keyboardType = if (isPassword) KeyboardType.Password else KeyboardType.Text
    )
